<script lang="ts">
  import { onDestroy, onMount } from 'svelte'
  import Icon from '../common/Icon.svelte'
  import ChartCanvas from '../common/ChartCanvas.svelte'
  import { Icons } from '../../icons'
  import {
    ruleEngineStore, queryBuilderStore, simulationStore, insightsStore,
    workflowBuilderStore, approvalEngineStore, taskSchedulerStore,
    notificationPipelineStore, replaceFeatureItems,
  } from '../../stores/features'
  import type { Rule, RuleAction, RuleCondition } from '../../../features/rule-engine/types'
  import { actionConfigs, availableFields, getOperatorsForFieldType, ruleTemplates } from '../../../features/rule-engine/config'
  import { createEmptyAction, createEmptyCondition, createEmptyRule, executeRules, validateRule } from '../../../features/rule-engine/engine'
  import type { Query, QueryFilter, QueryExportFormat } from '../../../features/query-builder/types'
  import { queryFields, queryPresets, getOperatorsForType } from '../../../features/query-builder/config'
  import { createEmptyFilter, createEmptyQuery, executeQuery, exportQuery } from '../../../features/query-builder/engine'
  import type { StreamConfig, TimeSeriesDataPoint } from '../../../features/real-time-simulation/types'
  import { streamPresets, streamTypeConfig } from '../../../features/real-time-simulation/config'
  import { calculateStatistics, generateDataPoint } from '../../../features/real-time-simulation/engine'
  import type { Insight, DataPoint, TimeSeries } from '../../../features/smart-insights/types'
  import { categoryConfig as insightCategories, priorityConfig as insightPriorities, sampleMetrics, generateSampleData } from '../../../features/smart-insights/config'
  import { analyzeTrend, generateInsights } from '../../../features/smart-insights/engine'
  import type { Workflow, WorkflowNodeType } from '../../../features/workflow-builder/types'
  import { nodeTemplates, nodeTypeColors, workflowTemplates } from '../../../features/workflow-builder/config'
  import { createEmptyWorkflow, createNode, validateWorkflow } from '../../../features/workflow-builder/engine'
  import type { StateMachine, StateMachineTemplate } from '../../../features/approval-engine/types'
  import { stateMachineTemplates } from '../../../features/approval-engine/config'
  import { createEmptyStateMachine, createInstance, createState, createTransition, validateStateMachine } from '../../../features/approval-engine/engine'
  import type { Task, TaskPriority, TaskStatus } from '../../../features/task-scheduler/types'
  import { priorityConfig as taskPriorities, statusConfig as taskStatuses, taskTemplates, generateSampleTasks } from '../../../features/task-scheduler/config'
  import { calculateAnalytics as calculateTaskAnalytics, createTask, updateTaskStatus, validateSchedule } from '../../../features/task-scheduler/engine'
  import type { Notification, NotificationPriority, NotificationType } from '../../../features/notification-pipeline/types'
  import { channelConfig, notificationTypeConfig, priorityConfig as notificationPriorityConfig, notificationTemplates, defaultChannels, generateSampleNotifications } from '../../../features/notification-pipeline/config'
  import { calculateAnalytics as calculateNotificationAnalytics, createFromTemplate, createNotification, dismissNotification, markRead, sendNotification } from '../../../features/notification-pipeline/engine'

  export let path = '/features/rule-engine'
  type FeatureKey = 'rule-engine' | 'query-builder' | 'simulation' | 'insights' | 'workflow-builder' | 'approval-engine' | 'task-scheduler' | 'notification-pipeline'
  type RuleResult = ReturnType<typeof executeRules>[number]
  type QueryResult = ReturnType<typeof executeQuery<Record<string, unknown>>>
  type SelectEvent = Event & { currentTarget: HTMLSelectElement }
  type InputEventWithTarget = Event & { currentTarget: HTMLInputElement }

  const meta: Record<FeatureKey, { title: string; description: string; icon: string }> = {
    'rule-engine': { title: 'Rule Engine', description: 'Create transparent, testable business rules with conditions and actions.', icon: Icons.ruleEngine },
    'query-builder': { title: 'Query Builder', description: 'Build precise data queries with a visual, composable filter canvas.', icon: Icons.queryBuilder },
    simulation: { title: 'Real-Time Simulation', description: 'Monitor changing metrics and run scenarios with live feedback.', icon: Icons.simulation },
    insights: { title: 'Smart Insights', description: 'Surface patterns, anomalies and recommendations from your data.', icon: Icons.insights },
    'workflow-builder': { title: 'Workflow Builder', description: 'Connect triggers, logic and automations in a visual workflow.', icon: Icons.workflowBuilder },
    'approval-engine': { title: 'Approval Engine', description: 'Design approval states and manage pending decisions in one place.', icon: Icons.approvalEngine },
    'task-scheduler': { title: 'Task Scheduler', description: 'Schedule work, dependencies and recurring operations across teams.', icon: Icons.taskScheduler },
    'notification-pipeline': { title: 'Notification Pipeline', description: 'Route notifications through rules, preferences and delivery channels.', icon: Icons.notificationPipeline },
  }
  const notificationPriorities = {
    low: { ...notificationPriorityConfig.low, bgColor: 'bg-success-100', color: 'text-success-700' },
    medium: { ...notificationPriorityConfig.medium, bgColor: 'bg-info-100', color: 'text-info-700' },
    high: { ...notificationPriorityConfig.high, bgColor: 'bg-warning-100', color: 'text-warning-700' },
    urgent: { ...notificationPriorityConfig.urgent, bgColor: 'bg-danger-100', color: 'text-danger-700' },
    critical: { ...notificationPriorityConfig.critical, bgColor: 'bg-danger-100', color: 'text-danger-700' },
  }
  const sampleRows: Record<string, unknown>[] = [
    { user: { name: 'Sarah Connor', status: 'active', role: 'admin', loginCount: 24 }, order: { total: 2400, status: 'processing', region: 'EU' }, product: { stock: 7, name: 'Adminex Pro' } },
    { user: { name: 'John Smith', status: 'active', role: 'manager', loginCount: 14 }, order: { total: 480, status: 'delivered', region: 'NA' }, product: { stock: 80, name: 'Starter Kit' } },
    { user: { name: 'Emily Davis', status: 'inactive', role: 'user', loginCount: 2 }, order: { total: 1250, status: 'cancelled', region: 'EU' }, product: { stock: 4, name: 'Analytics Add-on' } },
    { user: { name: 'Alex Morgan', status: 'pending', role: 'user', loginCount: 1 }, order: { total: 3200, status: 'shipped', region: 'APAC' }, product: { stock: 36, name: 'Enterprise Support' } },
  ]

  $: featureKey = (path.split('/').pop() as FeatureKey) || 'rule-engine'
  $: currentMeta = meta[featureKey] ?? meta['rule-engine']
  let notice = ''
  function clone<T>(value: T): T { return JSON.parse(JSON.stringify(value)) as T }
  function valueOf(event: Event): string { return (event.currentTarget as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement).value }
  function inform(message: string): void { notice = message; window.setTimeout(() => { if (notice === message) notice = '' }, 2600) }
  function hydrateTasks(items: Task[]): Task[] { return items.map((task) => ({ ...task, createdAt: new Date(task.createdAt), updatedAt: new Date(task.updatedAt), scheduledStart: task.scheduledStart ? new Date(task.scheduledStart) : undefined, scheduledEnd: task.scheduledEnd ? new Date(task.scheduledEnd) : undefined, actualStart: task.actualStart ? new Date(task.actualStart) : undefined, actualEnd: task.actualEnd ? new Date(task.actualEnd) : undefined })) }
  function hydrateNotifications(items: Notification[]): Notification[] { return items.map((item) => ({ ...item, createdAt: new Date(item.createdAt), updatedAt: new Date(item.updatedAt), scheduledAt: item.scheduledAt ? new Date(item.scheduledAt) : undefined, sentAt: item.sentAt ? new Date(item.sentAt) : undefined, deliveredAt: item.deliveredAt ? new Date(item.deliveredAt) : undefined, readAt: item.readAt ? new Date(item.readAt) : undefined, expiresAt: item.expiresAt ? new Date(item.expiresAt) : undefined, deliveryResults: (item.deliveryResults ?? []).map((result) => ({ ...result, sentAt: result.sentAt ? new Date(result.sentAt) : undefined, deliveredAt: result.deliveredAt ? new Date(result.deliveredAt) : undefined })) })) }

  onMount(() => {
    if (!$ruleEngineStore.items.length) replaceFeatureItems(ruleEngineStore, ruleTemplates.slice(0, 3).map((item) => ({ ...clone(item.rule), id: `rule-${item.id}`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), triggerCount: 0 })))
    if (!$queryBuilderStore.items.length) replaceFeatureItems(queryBuilderStore, queryPresets.slice(0, 3).map((item) => ({ ...clone(item.query), id: `query-${item.id}`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() })))
    if (!$simulationStore.items.length) replaceFeatureItems(simulationStore, streamPresets.slice(0, 3).map((item) => ({ ...clone(item.config), id: `stream-${item.id}`, isActive: false })))
    if (!$workflowBuilderStore.items.length) replaceFeatureItems(workflowBuilderStore, workflowTemplates.slice(0, 2).map((item) => ({ ...clone(item.workflow), id: `workflow-${item.id}`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() })))
    if (!$approvalEngineStore.items.length) replaceFeatureItems(approvalEngineStore, stateMachineTemplates.slice(0, 2).map((item: StateMachineTemplate) => ({ ...clone(item.machine), id: `machine-${item.id}`, metadata: { createdAt: new Date(), updatedAt: new Date(), createdBy: 'system', tags: [], category: item.category } })))
    if (!$taskSchedulerStore.items.length) replaceFeatureItems(taskSchedulerStore, generateSampleTasks())
    else replaceFeatureItems(taskSchedulerStore, hydrateTasks($taskSchedulerStore.items))
    if (!$notificationPipelineStore.items.length) replaceFeatureItems(notificationPipelineStore, generateSampleNotifications())
    else replaceFeatureItems(notificationPipelineStore, hydrateNotifications($notificationPipelineStore.items))
    if ($simulationStore.items.length) { simulationStreamId = $simulationStore.items[0].id; selectSimulationStream(simulationStreamId) }
    if (!$ruleEngineStore.items.length) return
    selectRule($ruleEngineStore.items[0])
  })

  // Rule engine state and actions
  let editingRule: Rule | null = null
  let selectedRuleId = ''
  let rulePayload = '{ "order": { "total": 1500, "status": "processing" }, "product": { "stock": 6 } }'
  let ruleResult: RuleResult | null = null
  $: ruleValidation = editingRule ? validateRule(editingRule) : { valid: false, errors: [] }
  function ruleConditions(rule: Rule): RuleCondition[] { return rule.conditionGroup.conditions.filter((item): item is RuleCondition => 'field' in item) }
  function selectRule(rule: Rule): void { selectedRuleId = rule.id; editingRule = clone(rule) }
  function newRule(): void { const rule = createEmptyRule(); rule.name = 'Untitled rule'; selectRule(rule) }
  function saveRule(): void { if (!editingRule || !ruleValidation.valid) return; const rule = { ...editingRule, updatedAt: new Date().toISOString() }; replaceFeatureItems(ruleEngineStore, $ruleEngineStore.items.some((item) => item.id === rule.id) ? $ruleEngineStore.items.map((item) => item.id === rule.id ? rule : item) : [...$ruleEngineStore.items, rule]); selectRule(rule); inform('Rule saved') }
  function addRuleTemplate(id: string): void { const template = ruleTemplates.find((item) => item.id === id); if (!template) return; const rule = { ...clone(template.rule), id: `rule-${Date.now()}`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), triggerCount: 0 }; replaceFeatureItems(ruleEngineStore, [...$ruleEngineStore.items, rule]); selectRule(rule); inform('Rule template added') }
  function deleteRule(): void { if (!editingRule) return; replaceFeatureItems(ruleEngineStore, $ruleEngineStore.items.filter((item) => item.id !== editingRule?.id)); editingRule = null; selectedRuleId = '' }
  function updateCondition(id: string, patch: Partial<RuleCondition>): void { if (!editingRule) return; editingRule = { ...editingRule, conditionGroup: { ...editingRule.conditionGroup, conditions: editingRule.conditionGroup.conditions.map((item) => 'field' in item && item.id === id ? { ...item, ...patch } : item) } } }
  function changeConditionField(id: string, fieldName: string): void { const field = availableFields.find((item) => item.name === fieldName); updateCondition(id, { field: fieldName, fieldType: field?.type ?? 'string', operator: getOperatorsForFieldType(field?.type ?? 'string')[0]?.value ?? 'equals', value: field?.type === 'number' ? 0 : '' }) }
  function addCondition(): void { if (editingRule) editingRule = { ...editingRule, conditionGroup: { ...editingRule.conditionGroup, conditions: [...editingRule.conditionGroup.conditions, createEmptyCondition()] } } }
  function removeCondition(id: string): void { if (!editingRule) return; const conditions = editingRule.conditionGroup.conditions.filter((item) => item.id !== id); editingRule = { ...editingRule, conditionGroup: { ...editingRule.conditionGroup, conditions: conditions.length ? conditions : [createEmptyCondition()] } } }
  function addAction(): void { if (editingRule) editingRule = { ...editingRule, actions: [...editingRule.actions, createEmptyAction()] } }
  function changeAction(id: string, type: RuleAction['type']): void { if (editingRule) editingRule = { ...editingRule, actions: editingRule.actions.map((item) => item.id === id ? { ...item, type, config: {} } : item) } }
  function runRule(): void { try { ruleResult = executeRules(editingRule ? [editingRule] : $ruleEngineStore.items, JSON.parse(rulePayload) as Record<string, unknown>)[0] ?? null } catch { inform('Enter valid JSON to test the rule') } }

  // Query builder state and actions
  let queryDraft: Query = createEmptyQuery()
  let queryFormat: QueryExportFormat = 'json'
  let queryResult: QueryResult | null = null
  let queryOutput = ''
  function filters(query: Query): QueryFilter[] { return query.filterGroup.filters.filter((item): item is QueryFilter => 'field' in item) }
  function changeFilter(id: string, patch: Partial<QueryFilter>): void { queryDraft = { ...queryDraft, filterGroup: { ...queryDraft.filterGroup, filters: queryDraft.filterGroup.filters.map((item) => 'field' in item && item.id === id ? { ...item, ...patch } : item) } } }
  function changeFilterField(id: string, name: string): void { const field = queryFields.find((item) => item.name === name); changeFilter(id, { field: name, fieldType: field?.type ?? 'string', operator: getOperatorsForType(field?.type ?? 'string')[0]?.value ?? 'eq', value: field?.type === 'number' ? 0 : '' }) }
  function addFilter(): void { queryDraft = { ...queryDraft, filterGroup: { ...queryDraft.filterGroup, filters: [...queryDraft.filterGroup.filters, createEmptyFilter()] } } }
  function removeFilter(id: string): void { const next = queryDraft.filterGroup.filters.filter((item) => item.id !== id); queryDraft = { ...queryDraft, filterGroup: { ...queryDraft.filterGroup, filters: next.length ? next : [createEmptyFilter()] } } }
  function loadPreset(id: string): void { const item = queryPresets.find((preset) => preset.id === id); if (item) queryDraft = { ...clone(item.query), id: `query-${Date.now()}`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() } }
  function saveQuery(): void { const query = { ...queryDraft, name: queryDraft.name.trim() || 'Untitled query', updatedAt: new Date().toISOString() }; queryDraft = query; replaceFeatureItems(queryBuilderStore, $queryBuilderStore.items.some((item) => item.id === query.id) ? $queryBuilderStore.items.map((item) => item.id === query.id ? query : item) : [...$queryBuilderStore.items, query]); inform('Query saved') }
  function runQuery(): void { queryResult = executeQuery(queryDraft, sampleRows); queryOutput = exportQuery(queryDraft, queryFormat) }

  // Real-time simulation state and actions
  let simulationStreamId = ''
  let simulationData: TimeSeriesDataPoint[] = []
  let simulationLastValue = 0
  let simulationTick = 0
  let simulationRunning = false
  let simulationTimer: ReturnType<typeof setInterval> | null = null
  $: activeStream = $simulationStore.items.find((item) => item.id === simulationStreamId) ?? null
  $: simulationStats = calculateStatistics(simulationData)
  $: simulationChart = { labels: simulationData.map((item) => item.label ?? new Date(item.timestamp).toLocaleTimeString()), datasets: [{ label: activeStream?.name ?? 'Stream', data: simulationData.map((item) => item.value), borderColor: activeStream ? streamTypeConfig[activeStream.type].color : '#3b82f6', backgroundColor: 'rgba(59,130,246,.14)', fill: true, tension: 0.35, pointRadius: 0 }] }
  function selectSimulationStream(id: string): void { simulationStreamId = id; simulationData = []; simulationTick = 0; simulationLastValue = $simulationStore.items.find((item) => item.id === id)?.baseValue ?? 0; for (let i = 0; i < 24; i += 1) appendSimulationPoint() }
  function appendSimulationPoint(): void { const stream = $simulationStore.items.find((item) => item.id === simulationStreamId); if (!stream) return; const point = generateDataPoint(stream, simulationLastValue || stream.baseValue, simulationTick); simulationData = [...simulationData.slice(-59), point]; simulationLastValue = point.value; simulationTick += 1 }
  function stopSimulation(): void { simulationRunning = false; if (simulationTimer) clearInterval(simulationTimer); simulationTimer = null }
  function startSimulation(): void { stopSimulation(); simulationRunning = true; appendSimulationPoint(); simulationTimer = setInterval(appendSimulationPoint, activeStream?.updateInterval ?? 1000) }
  function addStream(id: string): void { const preset = streamPresets.find((item) => item.id === id); if (!preset) return; const stream: StreamConfig = { ...clone(preset.config), id: `stream-${Date.now()}`, isActive: false }; replaceFeatureItems(simulationStore, [...$simulationStore.items, stream]); selectSimulationStream(stream.id) }

  // Smart insights state and actions
  let insightMetricId = 'revenue'
  let insightData: DataPoint[] = generateSampleData(90, 10000, 500, 3, true)
  let insightItems: Insight[] = []
  $: insightMetric = sampleMetrics.find((item) => item.id === insightMetricId)
  $: insightTrend = analyzeTrend(insightData, 30)
  $: insightChart = { labels: insightData.slice(-30).map((item) => new Date(item.timestamp).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })), datasets: [{ label: insightMetric?.name ?? 'Metric', data: insightData.slice(-30).map((item) => item.value), borderColor: '#8b5cf6', backgroundColor: 'rgba(139,92,246,.15)', fill: true, tension: 0.35, pointRadius: 1 }] }
  function analyzeInsights(): void { const series: TimeSeries = { id: insightMetricId, name: insightMetric?.name ?? 'Metric', data: insightData }; const dismissed = new Set($insightsStore.items.map((item) => item.id)); insightItems = generateInsights(series, undefined, insightMetric).filter((item) => !dismissed.has(item.id)); inform(`${insightItems.length} insights generated`) }
  function dismissInsight(item: Insight): void { replaceFeatureItems(insightsStore, [...$insightsStore.items, item]); insightItems = insightItems.filter((insight) => insight.id !== item.id) }
  function refreshInsights(): void { insightData = generateSampleData(90, insightMetric?.thresholds?.target ?? 1000, 50, 0.5, true); analyzeInsights() }

  // Workflow builder state and actions
  let workflowDraft: Workflow = createEmptyWorkflow()
  $: workflowValidation = validateWorkflow(workflowDraft)
  function addWorkflowNode(type: WorkflowNodeType): void { workflowDraft = { ...workflowDraft, nodes: [...workflowDraft.nodes, createNode(type, { x: workflowDraft.nodes.length * 180, y: 80 })], updatedAt: new Date().toISOString() } }
  function loadWorkflow(id: string): void { const item = workflowTemplates.find((template) => template.id === id); if (item) workflowDraft = { ...clone(item.workflow), id: `workflow-${Date.now()}`, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), runCount: 0 } }
  function saveWorkflow(): void { replaceFeatureItems(workflowBuilderStore, $workflowBuilderStore.items.some((item) => item.id === workflowDraft.id) ? $workflowBuilderStore.items.map((item) => item.id === workflowDraft.id ? workflowDraft : item) : [...$workflowBuilderStore.items, workflowDraft]); inform('Workflow saved') }

  // Approval engine state and actions
  let machineDraft: StateMachine = createEmptyStateMachine()
  let approvalInstance = createInstance(machineDraft)
  $: machineValidation = validateStateMachine(machineDraft)
  function addState(): void { const state = createState(`State ${machineDraft.states.length + 1}`); machineDraft = { ...machineDraft, states: [...machineDraft.states, state], metadata: { ...machineDraft.metadata, updatedAt: new Date() } } }
  function addTransition(): void { if (machineDraft.states.length < 2) return; const to = machineDraft.states[1]; const transition = createTransition(`Move to ${to.name}`, machineDraft.states[0].id, to.id, { requiresApproval: true }); machineDraft = { ...machineDraft, transitions: [...machineDraft.transitions, transition], metadata: { ...machineDraft.metadata, updatedAt: new Date() } } }
  function loadMachine(item: StateMachineTemplate): void { machineDraft = { ...clone(item.machine), id: `machine-${Date.now()}`, metadata: { createdAt: new Date(), updatedAt: new Date(), createdBy: 'system', tags: [], category: item.category } }; approvalInstance = createInstance(machineDraft) }
  function saveMachine(): void { replaceFeatureItems(approvalEngineStore, $approvalEngineStore.items.some((item) => item.id === machineDraft.id) ? $approvalEngineStore.items.map((item) => item.id === machineDraft.id ? machineDraft : item) : [...$approvalEngineStore.items, machineDraft]); inform('State machine saved') }

  // Task scheduler state and actions
  let taskName = ''
  let taskPriority: TaskPriority = 'medium'
  $: tasks = hydrateTasks($taskSchedulerStore.items)
  $: taskAnalytics = tasks.length ? calculateTaskAnalytics(tasks) : null
  $: scheduleValidation = tasks.length ? validateSchedule(tasks) : null
  function addTask(): void { if (!taskName.trim()) return; replaceFeatureItems(taskSchedulerStore, [...tasks, createTask(taskName.trim(), { priority: taskPriority, duration: 60, tags: ['new'] })]); taskName = ''; inform('Task added') }
  function addTaskTemplate(id: string): void { const item = taskTemplates.find((template) => template.id === id); if (!item) return; replaceFeatureItems(taskSchedulerStore, [...tasks, createTask(item.name, { description: item.description, priority: item.defaultPriority, duration: item.defaultDuration, tags: [item.category] })]); inform('Task template added') }
  function changeTaskStatus(task: Task, status: TaskStatus): void { const result = updateTaskStatus(task, status, tasks); replaceFeatureItems(taskSchedulerStore, tasks.map((item) => item.id === result.updatedTask.id ? result.updatedTask : result.affectedTasks.find((affected) => affected.id === item.id) ?? item)) }

  // Notification pipeline state and actions
  let notificationTitle = ''
  let notificationMessage = ''
  let notificationType: NotificationType = 'info'
  let notificationPriority: NotificationPriority = 'medium'
  $: notifications = hydrateNotifications($notificationPipelineStore.items)
  $: notificationAnalytics = notifications.length ? calculateNotificationAnalytics(notifications) : null
  function addNotification(): void { if (!notificationTitle.trim() || !notificationMessage.trim()) return; const item = createNotification({ type: notificationType, priority: notificationPriority, title: notificationTitle.trim(), message: notificationMessage.trim(), userId: 'user-1', channels: ['in_app'], category: 'general' }); replaceFeatureItems(notificationPipelineStore, [item, ...notifications]); notificationTitle = ''; notificationMessage = ''; inform('Notification queued') }
  function addNotificationTemplate(id: string): void { const template = notificationTemplates.find((item) => item.id === id); if (!template) return; replaceFeatureItems(notificationPipelineStore, [createFromTemplate(template, 'user-1', { userName: 'Adminex user' }), ...notifications]); inform('Notification created') }
  function notificationAction(item: Notification, action: 'read' | 'dismiss' | 'send'): void { const next = action === 'read' ? markRead(item) : action === 'dismiss' ? dismissNotification(item) : sendNotification(item, defaultChannels); replaceFeatureItems(notificationPipelineStore, notifications.map((entry) => entry.id === item.id ? next : entry)) }

  onDestroy(stopSimulation)
</script>

<svelte:head><title>{currentMeta.title} - Adminex</title></svelte:head>

<div class="space-y-6 animate-fade-in">
  <header class="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
    <div>
      <div class="flex items-center gap-3"><h1 class="heading-2 text-secondary-900 dark:text-white flex items-center gap-2"><Icon icon={currentMeta.icon} width={28} height={28} />{currentMeta.title}</h1><span class="px-2.5 py-1 text-xs font-semibold rounded-full bg-theme-primary-light text-theme-primary">Feature</span></div>
      <p class="text-body-sm text-secondary-500 dark:text-secondary-400 mt-1">{currentMeta.description}</p>
    </div>
    {#if notice}<div role="status" class="px-4 py-2.5 rounded-xl bg-success-100 text-success-700 text-sm font-medium">{notice}</div>{/if}
  </header>

  {#if featureKey === 'rule-engine'}
    <div class="grid grid-cols-1 xl:grid-cols-[280px_1fr] gap-6">
      <aside class="card rounded-xl p-4">
        <div class="flex items-center justify-between"><h2 class="font-semibold text-secondary-900 dark:text-white">Rules</h2><button type="button" aria-label="Create rule" class="p-2 text-theme-primary" on:click={newRule}><Icon icon={Icons.plus} /></button></div>
        <button type="button" class="btn-theme-primary w-full py-2.5 rounded-lg mt-4 text-sm" on:click={newRule}>Create rule</button>
        <div class="space-y-2 mt-5">{#each $ruleEngineStore.items as rule}<button type="button" class={`w-full text-left p-3 rounded-xl ${selectedRuleId === rule.id ? 'bg-theme-primary-light' : 'hover:bg-surface-100 dark:hover:bg-surface-800'}`} on:click={() => selectRule(rule)}><span class="flex items-center gap-2"><span class={`w-2 h-2 rounded-full ${rule.enabled ? 'bg-success-500' : 'bg-secondary-300'}`}></span><span class="text-sm font-semibold text-secondary-900 dark:text-white truncate">{rule.name || 'Untitled rule'}</span></span><span class="text-xs text-secondary-500 block mt-1">Priority {rule.priority} · {rule.actions.length} actions</span></button>{/each}</div>
        <div class="border-t border-surface-200 dark:border-surface-700 mt-5 pt-4"><p class="text-xs font-semibold uppercase tracking-wider text-secondary-500">Templates</p>{#each ruleTemplates as item}<button type="button" class="block text-left w-full text-xs text-secondary-600 dark:text-secondary-300 hover:text-theme-primary mt-3" on:click={() => addRuleTemplate(item.id)}>{item.name}</button>{/each}</div>
      </aside>
      <section class="space-y-6">
        {#if editingRule}
          <div class="card rounded-xl p-6">
            <div class="flex flex-col md:flex-row md:items-start md:justify-between gap-4"><div class="flex-1"><input bind:value={editingRule.name} aria-label="Rule name" class="text-xl font-semibold w-full bg-transparent border-b border-transparent focus:border-theme-primary outline-none text-secondary-900 dark:text-white" placeholder="Rule name" /><textarea bind:value={editingRule.description} aria-label="Rule description" class="input-theme mt-3" rows="2" placeholder="Describe this rule"></textarea></div><div class="flex items-center gap-3"><label class="flex items-center gap-2 text-sm text-secondary-500"><input type="checkbox" bind:checked={editingRule.enabled} class="checkbox-theme" />Enabled</label><button type="button" aria-label="Delete rule" class="p-2 text-secondary-400 hover:text-danger-600" on:click={deleteRule}><Icon icon={Icons.trash} /></button></div></div>
            <div class="flex flex-wrap items-end justify-between gap-3 mt-5"><label class="text-sm text-secondary-600 dark:text-secondary-300">Priority<input type="number" min="0" bind:value={editingRule.priority} class="input-theme mt-1 w-32" /></label><div class="flex gap-2"><button type="button" class="px-4 py-2 rounded-lg border border-surface-200 dark:border-surface-700 text-sm" on:click={() => { if (editingRule) selectRule({ ...clone(editingRule), id: `rule-${Date.now()}`, name: `${editingRule.name} copy` }) }}>Duplicate</button><button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm" disabled={!ruleValidation.valid} on:click={saveRule}>Save rule</button></div></div>
          </div>
          <div class="card rounded-xl p-6">
            <div class="flex items-center justify-between"><div><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">Conditions</h2><p class="text-sm text-secondary-500 mt-1">All conditions must pass.</p></div><button type="button" class="text-sm text-theme-primary" on:click={addCondition}><Icon icon={Icons.plus} className="inline w-4 h-4 me-1" />Add condition</button></div>
            <div class="space-y-3 mt-5">{#each ruleConditions(editingRule) as condition}<div class="grid grid-cols-1 md:grid-cols-[1fr_180px_1fr_auto] gap-3 items-end p-3 rounded-xl bg-surface-50 dark:bg-surface-800/60"><label class="text-xs text-secondary-500">Field<select class="input-theme mt-1" value={condition.field} on:change={(event) => changeConditionField(condition.id, valueOf(event))}><option value="">Choose field</option>{#each availableFields as field}<option value={field.name}>{field.label}</option>{/each}</select></label><label class="text-xs text-secondary-500">Operator<select class="input-theme mt-1" value={condition.operator} on:change={(event) => updateCondition(condition.id, { operator: valueOf(event) as RuleCondition['operator'] })}>{#each getOperatorsForFieldType(condition.fieldType) as operator}<option value={operator.value}>{operator.label}</option>{/each}</select></label><label class="text-xs text-secondary-500">Value<input class="input-theme mt-1" value={String(condition.value ?? '')} on:input={(event) => updateCondition(condition.id, { value: valueOf(event) })} /></label><button type="button" aria-label="Remove condition" class="p-2 text-secondary-400 hover:text-danger-600" on:click={() => removeCondition(condition.id)}><Icon icon={Icons.trash} width={16} /></button></div>{/each}</div>
          </div>
          <div class="card rounded-xl p-6"><div class="flex items-center justify-between"><div><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">Actions</h2><p class="text-sm text-secondary-500 mt-1">Actions run in order after a match.</p></div><button type="button" class="text-sm text-theme-primary" on:click={addAction}><Icon icon={Icons.plus} className="inline w-4 h-4 me-1" />Add action</button></div><div class="space-y-3 mt-5">{#each editingRule.actions as action, index}<div class="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-3 items-end p-3 rounded-xl bg-surface-50 dark:bg-surface-800/60"><label class="text-xs text-secondary-500">Action {index + 1}<select class="input-theme mt-1" value={action.type} on:change={(event) => changeAction(action.id, valueOf(event) as RuleAction['type'])}>{#each actionConfigs as config}<option value={config.type}>{config.label}</option>{/each}</select></label><label class="text-xs text-secondary-500">Configuration<input class="input-theme mt-1" value={JSON.stringify(action.config)} aria-label={`Configuration for action ${index + 1}`} /></label><button type="button" aria-label="Remove action" class="p-2 text-secondary-400 hover:text-danger-600" on:click={() => { if (editingRule) editingRule = { ...editingRule, actions: editingRule.actions.filter((item) => item.id !== action.id) } }}><Icon icon={Icons.trash} width={16} /></button></div>{/each}</div></div>
          {#if ruleValidation.errors.length}<div role="alert" class="rounded-xl p-4 bg-danger-50 text-danger-700 text-sm">{#each ruleValidation.errors as error}<p>{error}</p>{/each}</div>{/if}
          <div class="card rounded-xl p-6"><div class="flex items-center justify-between"><div><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">Rule tester</h2><p class="text-sm text-secondary-500 mt-1">Evaluate the current rule against JSON.</p></div><button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm" on:click={runRule}>Run test</button></div><textarea bind:value={rulePayload} aria-label="Rule payload" class="input-theme font-mono text-xs mt-4" rows="5"></textarea>{#if ruleResult}<div class={`mt-4 rounded-xl p-4 ${ruleResult.matched ? 'bg-success-100 text-success-700' : 'bg-warning-100 text-warning-700'}`}><p class="font-semibold">{ruleResult.matched ? 'Matched' : 'Did not match'}</p><p class="text-sm mt-1">{ruleResult.conditionResults.filter((item) => item.passed).length} of {ruleResult.conditionResults.length} conditions passed.</p></div>{/if}</div>
        {:else}
          <div class="card rounded-xl p-12 text-center"><Icon icon={Icons.ruleEngine} width={48} height={48} className="mx-auto text-secondary-300" /><h2 class="heading-4 text-secondary-900 dark:text-white mt-4">Select a rule to edit</h2><p class="text-secondary-500 mt-2">Create a rule or choose one from the list.</p></div>
        {/if}
      </section>
    </div>

  {:else if featureKey === 'query-builder'}
    <div class="grid grid-cols-1 xl:grid-cols-[260px_1fr] gap-6"><aside class="card rounded-xl p-4"><div class="flex items-center justify-between"><h2 class="font-semibold text-secondary-900 dark:text-white">Saved queries</h2><button type="button" aria-label="New query" class="p-2 text-theme-primary" on:click={() => (queryDraft = createEmptyQuery())}><Icon icon={Icons.plus} /></button></div><div class="space-y-2 mt-5">{#each $queryBuilderStore.items as query}<button type="button" class="w-full text-left p-3 rounded-xl hover:bg-surface-100 dark:hover:bg-surface-800" on:click={() => (queryDraft = clone(query))}><p class="text-sm font-semibold text-secondary-900 dark:text-white">{query.name || 'Untitled query'}</p><span class="text-xs text-secondary-500">{query.filterGroup.filters.length} filters</span></button>{/each}</div><p class="text-xs uppercase tracking-wider font-semibold text-secondary-500 border-t border-surface-200 dark:border-surface-700 mt-5 pt-4">Presets</p>{#each queryPresets as item}<button type="button" class="block w-full text-left text-xs text-secondary-600 dark:text-secondary-300 hover:text-theme-primary mt-3" on:click={() => loadPreset(item.id)}>{item.name}</button>{/each}</aside><section class="space-y-6"><div class="card rounded-xl p-6"><div class="flex flex-col md:flex-row md:items-center md:justify-between gap-3"><div><input bind:value={queryDraft.name} aria-label="Query name" class="text-xl font-semibold bg-transparent border-b border-transparent focus:border-theme-primary outline-none text-secondary-900 dark:text-white" placeholder="Query name" /><p class="text-sm text-secondary-500 mt-2">Build and run a typed query against local mock data.</p></div><div class="flex gap-2"><button type="button" class="px-4 py-2 rounded-lg border border-surface-200 dark:border-surface-700 text-sm" on:click={saveQuery}>Save</button><button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm" on:click={runQuery}>Run query</button></div></div><div class="flex items-center gap-3 mt-6"><span class="text-xs uppercase tracking-wider font-semibold text-secondary-500">Match</span><select class="input-theme w-auto" value={queryDraft.filterGroup.logic} on:change={(event) => (queryDraft = { ...queryDraft, filterGroup: { ...queryDraft.filterGroup, logic: valueOf(event) as 'AND' | 'OR' } })}><option value="AND">All filters</option><option value="OR">Any filter</option></select></div><div class="space-y-3 mt-4">{#each filters(queryDraft) as filter}<div class="grid grid-cols-1 md:grid-cols-[1fr_170px_1fr_auto] gap-3 items-end p-3 rounded-xl bg-surface-50 dark:bg-surface-800/60"><label class="text-xs text-secondary-500">Field<select class="input-theme mt-1" value={filter.field} on:change={(event) => changeFilterField(filter.id, valueOf(event))}><option value="">Choose field</option>{#each queryFields as field}<option value={field.name}>{field.label}</option>{/each}</select></label><label class="text-xs text-secondary-500">Operator<select class="input-theme mt-1" value={filter.operator} on:change={(event) => changeFilter(filter.id, { operator: valueOf(event) as QueryFilter['operator'] })}>{#each getOperatorsForType(filter.fieldType) as operator}<option value={operator.value}>{operator.label}</option>{/each}</select></label><label class="text-xs text-secondary-500">Value<input class="input-theme mt-1" value={String(filter.value ?? '')} on:input={(event) => changeFilter(filter.id, { value: filter.fieldType === 'number' ? Number(valueOf(event)) : valueOf(event) })} /></label><button type="button" aria-label="Remove filter" class="p-2 text-secondary-400 hover:text-danger-600" on:click={() => removeFilter(filter.id)}><Icon icon={Icons.trash} width={16} /></button></div>{/each}</div><button type="button" class="text-sm text-theme-primary mt-4" on:click={addFilter}><Icon icon={Icons.plus} className="inline w-4 h-4 me-1" />Add filter</button></div><div class="grid grid-cols-1 lg:grid-cols-2 gap-6"><div class="card rounded-xl p-6"><div class="flex items-center justify-between"><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">Result preview</h2>{#if queryResult}<span class="text-xs text-secondary-500">{queryResult.filtered} matches · {queryResult.executionTime.toFixed(2)}ms</span>{/if}</div>{#if queryResult}<div class="overflow-x-auto mt-4"><table class="w-full text-left text-sm"><thead><tr class="border-b border-surface-200 dark:border-surface-700"><th class="py-3 text-xs uppercase text-secondary-500">User</th><th class="py-3 text-xs uppercase text-secondary-500">Order</th><th class="py-3 text-xs uppercase text-secondary-500">Region</th></tr></thead><tbody>{#each queryResult.data as row}<tr class="border-b border-surface-100 dark:border-surface-800"><td class="py-3 text-secondary-900 dark:text-white">{String((row.user as Record<string, unknown>)?.name ?? '')}</td><td class="py-3">${String((row.order as Record<string, unknown>)?.total ?? '')}</td><td class="py-3">{String((row.order as Record<string, unknown>)?.region ?? '')}</td></tr>{/each}</tbody></table></div>{:else}<div class="py-12 text-center text-secondary-500"><Icon icon={Icons.database} width={40} height={40} className="mx-auto text-secondary-300" /><p class="mt-3">Run the query to preview results.</p></div>{/if}</div><div class="card rounded-xl p-6"><div class="flex items-center justify-between"><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">Export</h2><select bind:value={queryFormat} class="input-theme w-auto"><option value="json">JSON</option><option value="sql">SQL</option><option value="mongodb">MongoDB</option><option value="graphql">GraphQL</option></select></div><button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm mt-4" on:click={() => (queryOutput = exportQuery(queryDraft, queryFormat))}>Generate export</button><pre class="mt-4 p-4 rounded-xl bg-surface-900 text-surface-100 text-xs overflow-auto min-h-40 whitespace-pre-wrap">{queryOutput || 'Your exported query will appear here.'}</pre></div></div></section></div>

  {:else if featureKey === 'simulation'}
    <div class="grid grid-cols-1 xl:grid-cols-[260px_1fr] gap-6"><aside class="card rounded-xl p-4"><div class="flex items-center justify-between"><h2 class="font-semibold text-secondary-900 dark:text-white">Streams</h2><button type="button" aria-label="Add stream" class="p-2 text-theme-primary" on:click={() => addStream(streamPresets[0].id)}><Icon icon={Icons.plus} /></button></div><div class="space-y-2 mt-5">{#each $simulationStore.items as stream}<button type="button" class={`w-full text-left p-3 rounded-xl ${stream.id === simulationStreamId ? 'bg-theme-primary-light' : 'hover:bg-surface-100 dark:hover:bg-surface-800'}`} on:click={() => { stopSimulation(); selectSimulationStream(stream.id) }}><span class="flex items-center gap-2"><span class="w-2 h-2 rounded-full" style={`background:${streamTypeConfig[stream.type].color}`}></span><span class="text-sm font-semibold text-secondary-900 dark:text-white">{stream.name}</span></span><span class="text-xs text-secondary-500 block mt-1">{streamTypeConfig[stream.type].label}</span></button>{/each}</div><p class="text-xs uppercase tracking-wider font-semibold text-secondary-500 mt-6">Presets</p>{#each streamPresets as item}<button type="button" class="block w-full text-left text-xs text-secondary-600 dark:text-secondary-300 hover:text-theme-primary mt-3" on:click={() => addStream(item.id)}>{item.name}</button>{/each}</aside><section class="space-y-6"><div class="card rounded-xl p-6"><div class="flex flex-col md:flex-row md:items-center md:justify-between gap-4"><div><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">{activeStream?.name ?? 'Select a stream'}</h2><p class="text-sm text-secondary-500 mt-1">{activeStream ? streamTypeConfig[activeStream.type].label : 'No stream selected'}</p></div>{#if simulationRunning}<button type="button" class="px-4 py-2 rounded-lg bg-warning-500 text-white text-sm" on:click={stopSimulation}>Pause</button>{:else}<button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm" on:click={startSimulation}>Start stream</button>{/if}</div><div class="mt-6"><ChartCanvas type="line" data={simulationChart} height={360} /></div></div><div class="grid grid-cols-2 lg:grid-cols-4 gap-4">{#each [{label:'Latest',value:simulationLastValue.toFixed(2)},{label:'Average',value:simulationStats.mean.toFixed(2)},{label:'Minimum',value:simulationStats.min.toFixed(2)},{label:'Maximum',value:simulationStats.max.toFixed(2)}] as stat}<div class="card rounded-xl p-4"><p class="text-xs uppercase tracking-wider text-secondary-500">{stat.label}</p><p class="heading-4 text-secondary-900 dark:text-white mt-2">{stat.value}</p></div>{/each}</div></section></div>

  {:else if featureKey === 'insights'}
    <div class="space-y-6"><div class="card rounded-xl p-6"><div class="flex flex-col md:flex-row md:items-center md:justify-between gap-4"><div><h2 class="text-lg font-semibold text-secondary-900 dark:text-white">Insight workspace</h2><p class="text-sm text-secondary-500 mt-1">Run the preserved analysis engine against a metric.</p></div><div class="flex gap-2"><select bind:value={insightMetricId} class="input-theme w-auto" aria-label="Metric">{#each sampleMetrics as item}<option value={item.id}>{item.name}</option>{/each}</select><button type="button" class="px-4 py-2 rounded-lg border border-surface-200 dark:border-surface-700 text-sm" on:click={refreshInsights}>Refresh</button><button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm" on:click={analyzeInsights}>Analyze</button></div></div><div class="grid grid-cols-2 md:grid-cols-4 gap-4 mt-6">{#each [{label:'Current',value:insightTrend.endValue.toLocaleString()},{label:'Change',value:`${insightTrend.changePercent.toFixed(1)}%`},{label:'Direction',value:insightTrend.direction},{label:'Confidence',value:`${Math.round(insightTrend.rSquared * 100)}%`}] as stat}<div class="p-4 rounded-xl bg-surface-50 dark:bg-surface-800/60"><p class="text-xs text-secondary-500">{stat.label}</p><p class="heading-4 text-secondary-900 dark:text-white mt-1 capitalize">{stat.value}</p></div>{/each}</div><div class="mt-6"><ChartCanvas type="line" data={insightChart} height={320} /></div></div><div class="grid grid-cols-1 lg:grid-cols-2 gap-4">{#each insightItems as item}<article class={`card rounded-xl p-5 border-s-4 ${insightPriorities[item.priority].borderColor}`}><div class="flex items-start justify-between gap-3"><div class="flex items-center gap-2"><span class={`p-2 rounded-lg ${insightCategories[item.category].bgColor}`}><Icon icon={insightCategories[item.category].icon} width={18} /></span><div><span class="text-xs uppercase text-secondary-500">{insightCategories[item.category].label}</span><h3 class="font-semibold text-secondary-900 dark:text-white mt-1">{item.title}</h3></div></div><button type="button" class="text-xs text-secondary-400" on:click={() => dismissInsight(item)}>Dismiss</button></div><p class="text-sm text-secondary-600 dark:text-secondary-300 mt-4">{item.description}</p><div class="text-xs text-secondary-500 mt-4">{Math.round(item.confidence * 100)}% confidence</div></article>{/each}{#if !insightItems.length}<div class="lg:col-span-2 card rounded-xl p-10 text-center text-secondary-500"><Icon icon={Icons.insights} width={42} className="mx-auto text-secondary-300" /><p class="mt-3">Run Analyze to generate insights.</p></div>{/if}</div></div>

  {:else if featureKey === 'workflow-builder'}
    <div class="grid grid-cols-1 xl:grid-cols-[240px_1fr] gap-6"><aside class="card rounded-xl p-4"><h2 class="font-semibold text-secondary-900 dark:text-white">Node palette</h2><div class="space-y-2 mt-4">{#each nodeTemplates as item}<button type="button" class="w-full flex items-center gap-2 text-left p-2.5 rounded-lg hover:bg-surface-100 dark:hover:bg-surface-800" on:click={() => addWorkflowNode(item.type)}><span class="w-7 h-7 rounded-lg flex items-center justify-center text-white" style={`background:${nodeTypeColors[item.type]}`}><Icon icon={item.icon} width={15} /></span><span class="text-sm text-secondary-700 dark:text-secondary-300">{item.label}</span></button>{/each}</div><p class="text-xs uppercase tracking-wider font-semibold text-secondary-500 mt-6">Templates</p>{#each workflowTemplates as item}<button type="button" class="block text-left text-xs text-secondary-600 dark:text-secondary-300 hover:text-theme-primary mt-3" on:click={() => loadWorkflow(item.id)}>{item.name}</button>{/each}</aside><section class="space-y-6"><div class="card rounded-xl p-6"><div class="flex items-center justify-between gap-3"><div><input bind:value={workflowDraft.name} aria-label="Workflow name" class="text-xl font-semibold bg-transparent border-b border-transparent focus:border-theme-primary outline-none text-secondary-900 dark:text-white" /><p class="text-sm text-secondary-500 mt-2">Add nodes, then validate and save the workflow.</p></div><button type="button" class="btn-theme-primary px-4 py-2 rounded-lg text-sm" on:click={saveWorkflow}>Save workflow</button></div><div class="min-h-72 mt-6 rounded-xl bg-surface-50 dark:bg-surface-800/60 p-5"><div class="flex flex-wrap gap-4">{#each workflowDraft.nodes as node}<div class="w-44 bg-white dark:bg-surface-900 rounded-xl border border-surface-200 dark:border-surface-700 p-4"><div class="flex items-center justify-between"><span class="text-xs uppercase" style={`color:${nodeTypeColors[node.type]}`}>{node.type}</span><button type="button" class="text-secondary-400" aria-label={`Remove ${node.name}`} on:click={() => (workflowDraft = { ...workflowDraft, nodes: workflowDraft.nodes.filter((item) => item.id !== node.id) })}><Icon icon={Icons.x} width={15} /></button></div><p class="font-semibold text-sm text-secondary-900 dark:text-white mt-3">{node.name}</p><p class="text-xs text-secondary-500 mt-1">{node.inputs.length} inputs · {node.outputs.length} outputs</p></div>{/each}{#if !workflowDraft.nodes.length}<p class="text-sm text-secondary-500 py-12 w-full text-center">Choose a node from the palette to start.</p>{/if}</div></div></div><div class={`rounded-xl p-5 ${workflowValidation.isValid ? 'bg-success-50' : 'bg-warning-50'}`}><p class="font-semibold text-secondary-900">{workflowValidation.isValid ? 'Workflow is valid' : 'Validation needs attention'}</p>{#each [...workflowValidation.errors, ...workflowValidation.warnings].slice(0, 5) as error}<p class="text-sm text-secondary-600 mt-2">{error.message}</p>{/each}</div></section></div>

  {:else if featureKey === 'approval-engine'}
    <div class="grid grid-cols-1 xl:grid-cols-[260px_1fr] gap-6"><aside class="card rounded-xl p-4"><h2 class="font-semibold text-secondary-900 dark:text-white">State machine templates</h2>{#each stateMachineTemplates as item}<button type="button" class="w-full text-left p-3 rounded-xl hover:bg-surface-100 dark:hover:bg-surface-800 mt-3" on:click={() => loadMachine(item)}><p class="text-sm font-semibold text-secondary-900 dark:text-white">{item.name}</p><p class="text-xs text-secondary-500 mt-1">{item.description}</p></button>{/each}</aside><section class="space-y-6"><div class="card rounded-xl p-6"><div class="flex flex-col md:flex-row md:items-center md:justify-between gap-3"><div><input bind:value={machineDraft.name} aria-label="State machine name" class="text-xl font-semibold bg-transparent border-b border-transparent focus:border-theme-primary outline-none text-secondary-900 dark:text-white" /><p class="text-sm text-secondary-500 mt-2">Model states, transitions and approvals.</p></div><div class="flex gap-2"><button type="button" class="px-3 py-2 rounded-lg border border-surface-200 dark:border-surface-700 text-sm" on:click={addState}>Add state</button><button type="button" class="px-3 py-2 rounded-lg border border-surface-200 dark:border-surface-700 text-sm" on:click={addTransition}>Add transition</button><button type="button" class="btn-theme-primary px-3 py-2 rounded-lg text-sm" on:click={saveMachine}>Save</button></div></div><div class="grid grid-cols-1 md:grid-cols-3 gap-3 mt-6">{#each machineDraft.states as state}<div class="p-4 rounded-xl border border-surface-200 dark:border-surface-700" style={`border-top:3px solid ${state.metadata.color}`}><p class="font-semibold text-secondary-900 dark:text-white">{state.name}</p><p class="text-xs text-secondary-500 mt-1">{state.metadata.isInitial ? 'Initial' : state.metadata.isFinal ? 'Final' : 'Approval state'}</p></div>{/each}</div><div class="space-y-2 mt-5">{#each machineDraft.transitions as transition}<div class="flex items-center gap-3 p-3 rounded-xl bg-surface-50 dark:bg-surface-800/60 text-sm"><Icon icon={Icons.arrowRight} className="text-theme-primary" /><span class="text-secondary-900 dark:text-white">{transition.name}</span><span class="text-xs text-secondary-500">{transition.requiresApproval ? 'Approval required' : 'Automatic'}</span></div>{/each}</div></div><div class={`rounded-xl p-5 ${machineValidation.isValid ? 'bg-success-50' : 'bg-danger-50'}`}><p class="font-semibold text-secondary-900">{machineValidation.isValid ? 'State machine is valid' : 'Validation errors'}</p>{#each [...machineValidation.errors, ...machineValidation.warnings] as error}<p class="text-sm text-secondary-600 mt-2">{error.message}</p>{/each}</div><div class="card rounded-xl p-5 flex items-center justify-between"><div><p class="font-semibold text-secondary-900 dark:text-white">Instance simulator</p><p class="text-sm text-secondary-500 mt-1">Current state: {machineDraft.states.find((state) => state.id === approvalInstance.currentState)?.name ?? 'Unknown'}</p></div><button type="button" class="btn-theme-primary px-3 py-2 rounded-lg text-sm" on:click={() => (approvalInstance = createInstance(machineDraft))}>Reset instance</button></div></section></div>

  {:else if featureKey === 'task-scheduler'}
    <div class="space-y-6"><div class="card rounded-xl p-6"><div class="flex flex-col lg:flex-row lg:items-end gap-3"><label class="flex-1 text-sm text-secondary-600 dark:text-secondary-300">Task name<input bind:value={taskName} class="input-theme mt-1" placeholder="Add a task" on:keydown={(event) => event.key === 'Enter' && addTask()} /></label><label class="w-full lg:w-44 text-sm text-secondary-600 dark:text-secondary-300">Priority<select bind:value={taskPriority} class="input-theme mt-1">{#each Object.keys(taskPriorities) as priority}<option value={priority}>{taskPriorities[priority as TaskPriority].label}</option>{/each}</select></label><button type="button" class="btn-theme-primary px-4 py-2.5 rounded-lg text-sm" on:click={addTask}>Add task</button></div><div class="flex flex-wrap gap-2 mt-5">{#each taskTemplates as item}<button type="button" class="px-3 py-1.5 rounded-lg bg-surface-100 dark:bg-surface-800 text-xs text-secondary-600 dark:text-secondary-300" on:click={() => addTaskTemplate(item.id)}>{item.name}</button>{/each}</div></div><div class="grid grid-cols-2 lg:grid-cols-5 gap-4">{#each [{label:'Total',value:taskAnalytics?.totalTasks ?? 0},{label:'Completed',value:taskAnalytics?.completedTasks ?? 0},{label:'On track',value:taskAnalytics?.onTrackTasks ?? 0},{label:'Blocked',value:taskAnalytics?.blockedTasks ?? 0},{label:'Overdue',value:taskAnalytics?.overdueTasks.length ?? 0}] as stat}<div class="card rounded-xl p-4"><p class="text-xs uppercase text-secondary-500">{stat.label}</p><p class="heading-4 text-secondary-900 dark:text-white mt-2">{stat.value}</p></div>{/each}</div><div class="card rounded-xl overflow-hidden"><div class="p-5 border-b border-surface-200 dark:border-surface-700 flex items-center justify-between"><h2 class="font-semibold text-secondary-900 dark:text-white">Scheduled tasks</h2>{#if scheduleValidation}<span class={`text-xs ${scheduleValidation.isValid ? 'text-success-600' : 'text-danger-600'}`}>{scheduleValidation.isValid ? 'Schedule valid' : `${scheduleValidation.errors.length} errors`}</span>{/if}</div><div class="divide-y divide-surface-100 dark:divide-surface-800">{#each tasks as task}<div class="p-5 flex flex-col md:flex-row md:items-center gap-4"><span class="w-2 h-10 rounded-full" style={`background:${task.color ?? '#3b82f6'}`}></span><div class="flex-1"><p class="font-semibold text-secondary-900 dark:text-white">{task.name}</p><p class="text-sm text-secondary-500 mt-1">{task.description || 'No description'} · {task.duration} minutes</p><div class="flex flex-wrap gap-1.5 mt-2">{#each task.tags as tag}<span class="px-2 py-0.5 rounded bg-surface-100 dark:bg-surface-800 text-xs text-secondary-500">{tag}</span>{/each}</div></div><select class="input-theme w-full md:w-40" value={task.status} on:change={(event) => changeTaskStatus(task, valueOf(event) as TaskStatus)}>{#each Object.keys(taskStatuses) as status}<option value={status}>{taskStatuses[status as TaskStatus].label}</option>{/each}</select></div>{/each}</div></div></div>

  {:else if featureKey === 'notification-pipeline'}
    <div class="space-y-6"><div class="card rounded-xl p-6"><div class="grid grid-cols-1 lg:grid-cols-[1fr_1fr_auto] gap-3 items-end"><label class="text-sm text-secondary-600 dark:text-secondary-300">Title<input bind:value={notificationTitle} class="input-theme mt-1" placeholder="Notification title" /></label><label class="text-sm text-secondary-600 dark:text-secondary-300">Message<input bind:value={notificationMessage} class="input-theme mt-1" placeholder="Write a notification message" /></label><button type="button" class="btn-theme-primary px-4 py-2.5 rounded-lg text-sm" on:click={addNotification}>Queue notification</button></div><div class="flex flex-wrap gap-3 mt-4"><label class="text-xs text-secondary-500">Type<select bind:value={notificationType} class="input-theme mt-1 w-auto">{#each Object.keys(notificationTypeConfig) as type}<option value={type}>{notificationTypeConfig[type as NotificationType].label}</option>{/each}</select></label><label class="text-xs text-secondary-500">Priority<select bind:value={notificationPriority} class="input-theme mt-1 w-auto">{#each Object.keys(notificationPriorities) as priority}<option value={priority}>{notificationPriorities[priority as NotificationPriority].label}</option>{/each}</select></label><div><p class="text-xs text-secondary-500">Templates</p><div class="flex flex-wrap gap-2 mt-1">{#each notificationTemplates.slice(0, 4) as item}<button type="button" class="px-3 py-2 rounded-lg bg-surface-100 dark:bg-surface-800 text-xs" on:click={() => addNotificationTemplate(item.id)}>{item.name}</button>{/each}</div></div></div></div><div class="grid grid-cols-2 lg:grid-cols-4 gap-4">{#each [{label:'Sent',value:notificationAnalytics?.totalSent ?? 0},{label:'Delivered',value:notificationAnalytics?.totalDelivered ?? 0},{label:'Read',value:notificationAnalytics?.totalRead ?? 0},{label:'Delivery rate',value:`${(notificationAnalytics?.deliveryRate ?? 0).toFixed(0)}%`}] as stat}<div class="card rounded-xl p-4"><p class="text-xs uppercase text-secondary-500">{stat.label}</p><p class="heading-4 text-secondary-900 dark:text-white mt-2">{stat.value}</p></div>{/each}</div><div class="card rounded-xl overflow-hidden"><div class="p-5 border-b border-surface-200 dark:border-surface-700"><h2 class="font-semibold text-secondary-900 dark:text-white">Notification queue</h2></div><div class="divide-y divide-surface-100 dark:divide-surface-800">{#each notifications as item}<div class="p-5 flex flex-col md:flex-row md:items-start gap-4"><span class={`w-9 h-9 rounded-lg flex items-center justify-center ${notificationTypeConfig[item.type].bgColor} ${notificationTypeConfig[item.type].color}`}><Icon icon={notificationTypeConfig[item.type].icon} width={18} /></span><div class="flex-1"><div class="flex flex-wrap items-center gap-2"><p class="font-semibold text-secondary-900 dark:text-white">{item.title}</p><span class={`px-2 py-0.5 rounded-full text-xs ${notificationPriorities[item.priority].bgColor} ${notificationPriorities[item.priority].color}`}>{item.priority}</span><span class="text-xs text-secondary-500">{item.status}</span></div><p class="text-sm text-secondary-500 mt-1">{item.message}</p><p class="text-xs text-secondary-400 mt-2">{new Date(item.createdAt).toLocaleString()} · {item.channels.map((channel) => channelConfig[channel].label).join(', ')}</p></div><div class="flex gap-2"><button type="button" class="px-2.5 py-1.5 rounded-lg text-xs border border-surface-200 dark:border-surface-700" on:click={() => notificationAction(item, 'send')}>Send</button><button type="button" class="px-2.5 py-1.5 rounded-lg text-xs border border-surface-200 dark:border-surface-700" on:click={() => notificationAction(item, 'read')}>Read</button><button type="button" class="px-2.5 py-1.5 rounded-lg text-xs text-danger-600 border border-surface-200 dark:border-surface-700" on:click={() => notificationAction(item, 'dismiss')}>Dismiss</button></div></div>{/each}</div></div></div>
  {/if}
</div>
